#!/usr/bin/env bash
# Bundle item 140 commerce_smegov16_video (thread "Site: Add Commerce and Industry committee", 18 Nov 2569)
# sub-smegov meeting 16/2569 (12 Nov 2569): adds the POST-meeting video made by thread "Videos: Commerce and Industry committee
# meetings" (1080x1920, 3:27, Thai voice + English subtitles burned in, legal STOP 0 WARN 0; VIDEO AUTO-APPROVAL) and sets the
# easy-read text of item 138b with one wording change: the invited organisation is no longer named (matches the video).
# Self-sufficient: works whether or not 138b already ran (sets the whole meeting-16 entry: text, docs incl. summary ref 11204323,
# media). Surgical like items 75 and 138b: DATA[16] + sub-smegov.json[16] + SUBS[smegov][16] + SHARE_V[16] + CAPS, video share page
# via video_share.py (CARD_BIG=1) keeping every existing share page byte-identical, phone layer + no_video_dl on the new page.
# i18n-en.json: missing keys only. Idempotent; no git, no network. Needs $HUB ($BUILD optional).
set -euo pipefail
: "${HUB:?HUB not set}"; BUILD=${BUILD:-/mnt/project-files/archive/build}
# 140c = 140b with its payload (payload_140h.json, share files, legal check) embedded below, because the shared folder
# keeps dropping new files. Unpacked to a private temp folder; nothing else changes.
PAY="$(mktemp -d)"; trap 'rm -rf "$PAY"' EXIT
base64 -d > "$PAY/p.tgz" <<'B64'
