B64
tar -xzf "$PAY/p.tgz" -C "$PAY"; rm -f "$PAY/p.tgz"
test "$(md5sum < "$PAY/payload_140h.json" | cut -c1-32)" = 8fe4799157c535aa681432284570339e || { echo "140c: embedded payload damaged" >&2; exit 1; }
PJ="$PAY/payload_140h.json"
SRC=/mnt/project-files/committees/commerce/media     # the video thread's web copy (md5 in the .md)
M="$HUB/commerce/2569"
T=140_commerce_smegov16_video
for f in index.html sub-smegov.html sub-smegov.json i18n-en.json; do test -f "$M/$f" || { echo "$T: $M/$f missing" >&2; exit 1; }; done
test -s "$PJ" || { echo "$T: $PJ missing" >&2; exit 1; }
V="$SRC/sub-smegov-v16.mp4"
test -s "$V" -a -s "$SRC/sub-smegov-v16.th.vtt" -a -s "$SRC/poster-sub-smegov-16.jpg" || { echo "$T: media files missing in $SRC" >&2; exit 1; }
dur=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$V")
python3 -c "import sys; sys.exit(0 if abs(float('$dur')-207)<2 else 1)" || { echo "$T: length $dur, expected ~207 s" >&2; exit 1; }
wh=$(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$V"); [ "$wh" = "1080,1920" ] || { echo "$T: size $wh" >&2; exit 1; }
head -1 "$SRC/sub-smegov-v16.th.vtt" | grep -q '^WEBVTT' || { echo "$T: vtt header" >&2; exit 1; }
mkdir -p "$M/media" "$M/img"
# the mp4 is skipped when video_offload already moved it to a video repo (live media src then starts with /video-)
grep -q '/video-[0-9]*/commerce/2569/media/sub-smegov-v16.mp4' "$M/sub-smegov.html" || { cmp -s "$V" "$M/media/sub-smegov-v16.mp4" || cp -f "$V" "$M/media/sub-smegov-v16.mp4"; }
cmp -s "$SRC/sub-smegov-v16.th.vtt" "$M/media/sub-smegov-v16.th.vtt" || cp -f "$SRC/sub-smegov-v16.th.vtt" "$M/media/sub-smegov-v16.th.vtt"
cmp -s "$SRC/poster-sub-smegov-16.jpg" "$M/img/poster-sub-smegov-16.jpg" || cp -f "$SRC/poster-sub-smegov-16.jpg" "$M/img/poster-sub-smegov-16.jpg"
(cd "$PAY/files" && find . -type f) | while read -r f; do
  mkdir -p "$(dirname "$M/$f")"; cmp -s "$PAY/files/$f" "$M/$f" || cp -f "$PAY/files/$f" "$M/$f"; done
python3 - "$M" "$PJ" <<'PY'
import json, os, sys
M, PAYF = sys.argv[1], sys.argv[2]
P = json.load(open(PAYF, encoding='utf-8')); key, n = P['key'], P['n']
dec = json.JSONDecoder()
def one(lines, pre):
    idx = [i for i, l in enumerate(lines) if l.startswith(pre)]
    assert len(idx) == 1, f'140: {pre} not found once'; return idx[0]
def jline(lines, pre):
    i = one(lines, pre); body = lines[i][len(pre):]; val, end = dec.raw_decode(body); tail = body[end:]
    for dump in (lambda a: json.dumps(a, ensure_ascii=False), lambda a: json.dumps(a, ensure_ascii=False, separators=(',', ':')),
                 lambda a: json.dumps(a, ensure_ascii=False, separators=(',', ':')).replace('</', '<\\/')):
        if pre + dump(val) + tail == lines[i]: return i, val, tail, dump
    raise SystemExit(f'140: {pre} does not round-trip; not touching it')
def swap(arr, new):
    hit = [k for k, x in enumerate(arr) if x.get('n') == n]
    assert len(hit) == 1, f'140: meeting {n} not found once'
    arr[hit[0]] = new; return arr
def write(p, lines):
    t = '\n'.join(lines)
    if open(p, encoding='utf-8').read() != t: open(p, 'w', encoding='utf-8').write(t); print('140 changed', os.path.relpath(p, M))
def media(cur):
    # keep the live media when it already has this video (e.g. src already moved to /video-N/ by video_offload)
    if cur and cur.get('video', {}).get('ck') == 'smegov-16': return cur
    md = json.loads(json.dumps(P['media']))
    for v in [md['video']] + md['videos']:
        v['size'] = os.path.getsize(os.path.join(M, v['src']))
    return md
p = os.path.join(M, f'sub-{key}.html'); L = open(p, encoding='utf-8').read().split('\n')
i, arr, tail, dump = jline(L, 'const DATA=')
cur = [x for x in arr if x.get('n') == n][0]
new = dict(P['data']); new['media'] = media(cur.get('media'))
L[i] = 'const DATA=' + dump(swap(arr, new)) + tail
j = one(L, 'const SHARE_P='); pre = f'const SHARE_P="{key}-",SHARE_V='
assert L[j].startswith(pre), '140: SHARE_P line shape'
sv, end = dec.raw_decode(L[j], len(pre)); rest = L[j][end:]
assert pre + json.dumps(sv, ensure_ascii=False) + rest == L[j], '140: SHARE_P does not round-trip'
assert sv.get(str(n)) in (P['old_share_v'], P['share_v']), f'140: SHARE_V[{n}] changed on live since the payload was made'
sv[str(n)] = P['share_v']; L[j] = pre + json.dumps(sv, ensure_ascii=False) + rest
i, caps, tail, cdump = jline(L, 'const CAPS=')
for ck, vtt in P['caps'].items():
    caps[ck] = open(os.path.join(M, vtt), encoding='utf-8').read()
L[i] = 'const CAPS=' + cdump(caps) + tail
write(p, L)
jp = os.path.join(M, f'sub-{key}.json'); raw = open(jp, encoding='utf-8').read(); ms = json.loads(raw)
assert json.dumps(ms, ensure_ascii=False, indent=1) == raw.rstrip('\n'), f'140: sub-{key}.json does not round-trip'
cj = [x for x in ms if x.get('n') == n][0]; nj = dict(P['json']); nj['media'] = media(cj.get('media'))
out = json.dumps(swap(ms, nj), ensure_ascii=False, indent=1) + ('\n' if raw.endswith('\n') else '')
if out != raw: open(jp, 'w', encoding='utf-8').write(out); print(f'140 changed sub-{key}.json')
ip = os.path.join(M, 'index.html'); IL = open(ip, encoding='utf-8').read().split('\n')
i, subs, tail, dump = jline(IL, 'const SUBS=')
s = [x for x in subs if x['key'] == key]; assert len(s) == 1
swap(s[0]['meetings'], P['subs_meeting'])
IL[i] = 'const SUBS=' + dump(subs) + tail
write(ip, IL)
xp = os.path.join(M, 'i18n-en.json'); raw = open(xp, encoding='utf-8').read(); d = json.loads(raw)
assert json.dumps(d, ensure_ascii=False, separators=(',', ':')) == raw, '140: i18n-en.json format changed; not touching it'
add_en = {k: v for k, v in P['en'].items() if k not in d}
if add_en:
    d.update(add_en); open(xp, 'w', encoding='utf-8').write(json.dumps(d, ensure_ascii=False, separators=(',', ':'))); print('140 i18n +%d' % len(add_en))
PY
KEEP=$(mktemp -d); trap 'rm -rf "$KEEP" "$PAY"' EXIT
NEWP="v-smegov-16.html"
for f in "$M"/s/v-*.html; do b=$(basename "$f"); case " $NEWP " in *" $b "*) ;; *) cp -p "$f" "$KEEP/$b";; esac; done
if ! grep -q '"16":"s/v-smegov-16.html' "$M/sub-smegov.html" || [ ! -f "$M/s/v-smegov-16.html" ]; then
  CARD_BIG=1 python3 "$BUILD/video_share.py" "$M" https://parliamentx.com/commerce/2569 2569
  for b in $NEWP; do test -f "$M/s/$b" || { echo "$T: share page s/$b missing" >&2; exit 1; }; python3 "$BUILD/mobile.py" "$M/s/$b" >/dev/null; done
  python3 "$BUILD/no_video_dl.py" "$M/s"
  for f in "$KEEP"/*.html; do cmp -s "$f" "$M/s/$(basename "$f")" || cp -f "$f" "$M/s/$(basename "$f")"; done
fi
python3 "$BUILD/no_video_dl.py" --check "$M"
python3 - "$M" <<'PY'
import json, sys
M = sys.argv[1]; dec = json.JSONDecoder()
t = open(f'{M}/sub-smegov.html', encoding='utf-8').read()
for l in t.split('\n'):
    if l.startswith('const DATA='): d = {m['n']: m for m in dec.raw_decode(l[11:])[0]}
m = d[16]
assert [v['kind'] for v in m['media']['videos']] == ['post'] and m['media']['video']['ck'] == 'smegov-16', '16 post video'
assert m['headline'].startswith('รับฟังแนวทางป้องกันการทุจริต') and 'ประเทศไทย)' not in m['summary'] and 'ภาคเอกชนด้านการต่อต้านคอร์รัปชัน' in m['summary']
assert any(x['k'] == 'summary' and x['url'].endswith('ref=11204323') for x in m['docs']), 'summary doc'
for n in (12, 13): assert [v['kind'] for v in d[n]['media']['videos']] == ['post'], f'smegov {n} video lost'
assert d[17]['upcoming'] and [v['kind'] for v in d[17]['media']['videos']] == ['pre'], 'smegov 17 card/pre video'
assert '"16":"s/v-smegov-16.html' in t and '"smegov-16"' in t, 'VSHARE/CAPS'
assert 'id="vidkind-js"' in t and 'id="novdl-css"' in t, 'live layer missing'
js = {x['n']: x for x in json.load(open(f'{M}/sub-smegov.json', encoding='utf-8'))}
assert js[16]['summary'] == m['summary'] and js[16]['media']['video']['ck'] == 'smegov-16'
for b in ('v-smegov-16.html', 'v-smegov-13.html'):
    h = open(f'{M}/s/{b}', encoding='utf-8').read()
    assert '<style data-mb>' in h and 'id="novdl-css"' in h, f's/{b}: phone/no-download layer missing'
print('140_commerce_smegov16_video OK')
PY
